WITH Base AS (SELECT *, COALESCE(dept_name, 'unassigned') AS dept_name_filled FROM departments WHERE dept_name NOT IN ('Marketing', 'Sales', 'Finance') AND (location NOT IN ('Chiang Mai', 'New York') OR location IN ('Berlin', 'Chiang Mai', 'Tokyo'))), summary AS (SELECT location, ROUND((100 * SUM(CASE WHEN dept_name = 'Marketing' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_marketing, SUM(budget) AS total_budget FROM Base GROUP BY location) SELECT location, pct_marketing, total_budget FROM summary WHERE total_budget < 9218000;
